{

"kind": "propose",
"summary": "CPU limit too low, causing sustained throttling. Increase limit to 300m.",
"hypotheses": [
  {
    "root_cause_class": "cpu_limit_too_low",
    "summary": "Container is throttled at 90% of its 0.2 CPU limit (200m), with usage at 0.183 cores and logs showing consistent CPU backlogs.",
    "supporting": ["ev-container_cpu", "ev-container_logs_tail"],
    "contradicting": [],
    "missing": [],
    "status": "supported"
  }
],
"proposal": {
  "capability": "deployment.set-resources",
  "target": {
    "group": "apps",
    "kind": "Deployment",
    "namespace": "shop",
    "name": "search",
    "uid": "uid-deployment-search"
  },
  "params": {
    "containers": {
      "app": {
        "limits": {
          "cpu": "300m"
        }
      }
    }
  },
  "expected_effect": "Raise CPU limit to 300m, clearing throttling and allowing the container to keep up with CPU demand.",
  "rationale": "Container is throttled at 90% of its 0.2 CPU limit (200m) with usage at 0.183 cores, and logs show consistent CPU backlogs. Increasing limit to 1.5x current (300m) addresses sustained throttling without touching memory. No earlier revision exists to roll back.",
  "cited_evidence_ids": ["ev-container_cpu", "ev-container_logs_tail"],
  "cited_predicates": ["throttling_data_available", "cpu_throttled_at_limit", "cpu_usage_near_limit"]
}
}
